style:
/* 玄墨 —— 深色侧栏通到页顶，主栏标题是墨色小标牌 */

.tw-xuanmo.layout-sidebar.resume-paper {
  padding-top: 0;
}

.tw-xuanmo.layout-sidebar.resume-paper .paper-header {
  margin: 0 -15mm;
  padding: 10mm 15mm 6mm;
  background: #1f262b;
  border: none;
  color: #fff;
  align-items: flex-start;
  gap: 7mm;
  print-color-adjust: exact;
}

.tw-xuanmo.layout-sidebar.resume-paper .paper-photo {
  order: -1;
  width: 26mm;
  height: 34mm;
  border: 0.5mm solid rgba(255, 255, 255, 0.42);
  border-radius: 0;
  box-shadow: none;
}

.tw-xuanmo.layout-sidebar.resume-paper .paper-photo--monogram {
  display: grid;
  place-items: center;
  background: rgba(255, 255, 255, 0.12);
  color: #fff;
  font-size: calc(var(--paper-base-size) * 2);
  font-weight: 700;
}

.tw-xuanmo.layout-sidebar.resume-paper .paper-name {
  color: #fff;
  font-family: var(--paper-font-family);
  font-size: calc(var(--paper-base-size) * 2.05);
  letter-spacing: 0.08em;
}

.tw-xuanmo.layout-sidebar.resume-paper .paper-identity {
  padding: 0;
  border: none;
  color: rgba(255, 255, 255, 0.66);
  font-size: calc(var(--paper-base-size) * 0.84);
}

.tw-xuanmo.layout-sidebar.resume-paper .paper-role {
  margin-top: 1.6mm;
  color: rgba(255, 255, 255, 0.86);
  font-size: calc(var(--paper-base-size) * 0.9);
  font-weight: 400;
  line-height: 1.7;
}

.tw-xuanmo.layout-sidebar.resume-paper .paper-contacts {
  display: flex;
  flex-wrap: wrap;
  gap: 1.4mm 6mm;
  margin-top: 3mm;
  color: rgba(255, 255, 255, 0.88);
  font-size: calc(var(--paper-base-size) * 0.84);
}

.tw-xuanmo.layout-sidebar.resume-paper .paper-contact__label {
  color: rgba(255, 255, 255, 0.55);
}

/* 深色窄栏：铺到纸边，与页眉连成一块 */
.tw-xuanmo.layout-sidebar.resume-paper .sidebar-layout {
  align-items: stretch;
  grid-template-columns: 60mm minmax(0, 1fr);
  column-gap: 0;
}

.tw-xuanmo.layout-sidebar.resume-paper .sidebar-aside {
  grid-column: 1;
  margin: 0 0 0 -15mm;
  padding: 2mm 6mm 6mm 15mm;
  background: #1f262b;
  border-top: none;
  color: rgba(255, 255, 255, 0.9);
  print-color-adjust: exact;
}

.tw-xuanmo.layout-sidebar.resume-paper .sidebar-main {
  grid-column: 2;
  padding-left: 8mm;
}

.tw-xuanmo.layout-sidebar.resume-paper .sidebar-aside .paper-section__title {
  display: block;
  margin-bottom: 2.6mm;
  padding: 0 0 1.2mm;
  border: none;
  border-bottom: 0.25mm solid rgba(255, 255, 255, 0.28);
  color: #fff;
  font-size: calc(var(--paper-base-size) * 0.96);
  letter-spacing: 0.12em;
}

.tw-xuanmo.layout-sidebar.resume-paper .sidebar-aside .paper-section__icon {
  display: none;
}

.tw-xuanmo.layout-sidebar.resume-paper .sidebar-aside .paper-section__body,
.tw-xuanmo.layout-sidebar.resume-paper .sidebar-aside .paper-item-title,
.tw-xuanmo.layout-sidebar.resume-paper .sidebar-aside .paper-item-sub,
.tw-xuanmo.layout-sidebar.resume-paper .sidebar-aside .paper-item-period,
.tw-xuanmo.layout-sidebar.resume-paper .sidebar-aside .paper-rich,
.tw-xuanmo.layout-sidebar.resume-paper .sidebar-aside .paper-note,
.tw-xuanmo.layout-sidebar.resume-paper .sidebar-aside .paper-plain {
  color: rgba(255, 255, 255, 0.86);
}

.tw-xuanmo.layout-sidebar.resume-paper .sidebar-aside .paper-rich li::marker {
  color: var(--list-color, rgba(255, 255, 255, 0.6));
}

/* 主栏：墨色小标牌标题 */
.tw-xuanmo.layout-sidebar.resume-paper .sidebar-main .paper-section__title {
  display: inline-flex;
  align-items: center;
  gap: 2mm;
  margin-bottom: 3mm;
  padding: 1.2mm 4.4mm;
  background: #1f262b;
  border-radius: 1mm;
  color: #fff;
  font-size: calc(var(--paper-base-size) * 0.98);
  letter-spacing: 0.14em;
  print-color-adjust: exact;
}

.tw-xuanmo.layout-sidebar.resume-paper .sidebar-main .paper-section__icon {
  display: grid;
  flex: 0 0 auto;
  place-items: center;
  width: 3.8mm;
  height: 3.8mm;
  color: #fff;
}

.tw-xuanmo.layout-sidebar.resume-paper .sidebar-main .paper-section__icon svg {
  width: 100%;
  height: 100%;
}

.tw-xuanmo.layout-sidebar.resume-paper .sidebar-main .paper-section__body {
  color: #33393d;
}

.tw-xuanmo.layout-sidebar.resume-paper .sidebar-main .paper-item-title {
  color: #1f2427;
  font-size: calc(var(--paper-base-size) * 1.02);
}

.tw-xuanmo.layout-sidebar.resume-paper .sidebar-main .paper-item-period {
  color: #7d878c;
  font-size: calc(var(--paper-base-size) * 0.86);
}

.tw-xuanmo.layout-sidebar.resume-paper .sidebar-main .paper-item-sub {
  color: #465055;
}

.tw-xuanmo.layout-sidebar.resume-paper .paper-rich ul,
.tw-xuanmo.layout-sidebar.resume-paper .paper-rich ol {
  padding-left: 1.1em;
}

.tw-xuanmo.layout-sidebar.resume-paper .sidebar-main .paper-rich li::marker {
  color: var(--list-color, #8c969b);
}

/* 侧栏技能：白色分段进度条 */
.tw-xuanmo.layout-sidebar.resume-paper .sidebar-aside .paper-skills {
  grid-template-columns: minmax(0, 1fr);
  gap: 2mm;
}

.tw-xuanmo.layout-sidebar.resume-paper .sidebar-aside .paper-skill {
  position: relative;
  display: block;
  padding-bottom: 0;
  border-bottom: none;
}

.tw-xuanmo.layout-sidebar.resume-paper .sidebar-aside .paper-skill__name {
  display: block;
  color: rgba(255, 255, 255, 0.88);
  font-size: calc(var(--paper-base-size) * 0.86);
  font-weight: 400;
}

.tw-xuanmo.layout-sidebar.resume-paper .sidebar-aside .paper-skill__dots {
  display: flex;
  gap: 0;
  margin-top: 1mm;
}

.tw-xuanmo.layout-sidebar.resume-paper .sidebar-aside .paper-skill__dots i {
  width: 100%;
  height: 1.4mm;
  border-radius: 0;
  background: rgba(255, 255, 255, 0.22);
}

.tw-xuanmo.layout-sidebar.resume-paper .sidebar-aside .paper-skill__dots i.filled {
  background: #fff;
}

.tw-xuanmo.layout-sidebar.resume-paper .sidebar-aside .paper-skill__level {
  position: absolute;
  top: 0;
  right: 0;
  display: inline;
  color: rgba(255, 255, 255, 0.6);
  font-size: calc(var(--paper-base-size) * 0.76);
}

.tw-xuanmo.layout-sidebar.resume-paper .sidebar-aside .paper-note__tag {
  color: #fff;
  font-weight: 600;
}

.tw-xuanmo.layout-sidebar.resume-paper .paper-footer {
  border-top: 0.2mm solid #e3e6e8;
  color: #9aa3a8;
}

/* 显式选择的列表样式接管模板默认圆点装饰，避免 data-list 被模板 ul/li 规则盖掉。 */
.tw-xuanmo.resume-paper .paper-rich ul[data-list],
.tw-xuanmo.resume-paper .paper-rich ol[data-list] {
  margin: 0.5mm 0 0;
  padding-left: 1.2em;
}
.tw-xuanmo.resume-paper .paper-rich ul[data-list] > li,
.tw-xuanmo.resume-paper .paper-rich ol[data-list] > li {
  padding-left: 0;
  position: relative;
}
.tw-xuanmo.resume-paper .paper-rich ul[data-list] > li::before,
.tw-xuanmo.resume-paper .paper-rich ol[data-list] > li::before {
  content: none;
  width: auto;
  height: auto;
  border-radius: 0;
  background: none;
  border: 0;
  box-shadow: none;
  left: auto;
  right: auto;
  top: auto;
  margin: 0;
  padding: 0;
}
.tw-xuanmo.resume-paper .paper-rich ul[data-list="disc"] { list-style-type: disc; }
.tw-xuanmo.resume-paper .paper-rich ul[data-list="circle"] { list-style-type: circle; }
.tw-xuanmo.resume-paper .paper-rich ul[data-list="square"] { list-style-type: square; }
.tw-xuanmo.resume-paper .paper-rich ul[data-list="square-open"] { list-style-type: "□   "; }
.tw-xuanmo.resume-paper .paper-rich ul[data-list="square-open"] > li::marker { font-size: 0.62em; }
.tw-xuanmo.resume-paper .paper-rich ul[data-list="diamond"] { list-style-type: "◆   "; }
.tw-xuanmo.resume-paper .paper-rich ul[data-list="diamond-open"] { list-style-type: "◇   "; }
.tw-xuanmo.resume-paper .paper-rich ul[data-list="diamond"] > li::marker,
.tw-xuanmo.resume-paper .paper-rich ul[data-list="diamond-open"] > li::marker { font-size: 0.62em; }
.tw-xuanmo.resume-paper .paper-rich ul[data-list="triangle"] { list-style-type: "▸   "; }
.tw-xuanmo.resume-paper .paper-rich ul[data-list="check"] { list-style-type: "✓   "; }
.tw-xuanmo.resume-paper .paper-rich ul[data-list="check"] > li::marker { font-size: 0.75em; }
.tw-xuanmo.resume-paper .paper-rich ol[data-list="decimal"] { list-style-type: decimal; }
.tw-xuanmo.resume-paper .paper-rich ol[data-list="cjk"] { list-style-type: miniwho-cjk; }
.tw-xuanmo.resume-paper .paper-rich ol[data-list="roman-upper"] { list-style-type: upper-roman; }
.tw-xuanmo.resume-paper .paper-rich ol[data-list="roman-lower"] { list-style-type: lower-roman; }
.tw-xuanmo.resume-paper .paper-rich ol[data-list="alpha-upper"] { list-style-type: upper-alpha; }
.tw-xuanmo.resume-paper .paper-rich ol[data-list="alpha-lower"] { list-style-type: lower-alpha; }
.tw-xuanmo.resume-paper .paper-rich ol[data-list="paren"] { padding-left: 1.2em; list-style: none; counter-reset: paren-item; }
.tw-xuanmo.resume-paper .paper-rich ol[data-list="paren"] > li { position: relative; counter-increment: paren-item; }
.tw-xuanmo.resume-paper .paper-rich ol[data-list="paren"] > li::before {
  content: "（" counter(paren-item) "）";
  position: absolute;
  right: calc(100% + 0.08em);
  top: 0;
  font-family: var(--mono);
  font-variant-numeric: tabular-nums;
  font-size: 0.62em;
  line-height: 1.7;
  white-space: nowrap;
}
.tw-xuanmo.resume-paper .paper-rich ol[data-list="paren-right"] { padding-left: 1.2em; list-style: none; counter-reset: paren-right-item; }
.tw-xuanmo.resume-paper .paper-rich ol[data-list="paren-right"] > li { position: relative; counter-increment: paren-right-item; }
.tw-xuanmo.resume-paper .paper-rich ol[data-list="paren-right"] > li::before {
  content: counter(paren-right-item) ")";
  position: absolute;
  right: calc(100% + 0.12em);
  top: 0;
  font-family: var(--mono);
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
}
